package com.foodflow.orders.client;import com.foodflow.orders.dto.CouponResponse;import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.*;
@FeignClient(name="coupon-service",url="${foodflow.coupon.url:}",configuration=com.foodflow.orders.config.FeignConfig.class) public interface CouponClient{@GetMapping("/api/coupons/{code}/validate") CouponResponse validate(@PathVariable String code);@PostMapping("/api/coupons/{code}/redeem") CouponResponse redeem(@PathVariable String code);@PostMapping("/api/coupons/{code}/release") void release(@PathVariable String code);}
